function coffeeDate(offset=0){const d=new Date();d.setDate(d.getDate()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function coffeeDateLabel(iso:string){return new Date(iso+'T12:00:00').toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})}

function Button({children,onClick,secondary=false,disabled=false}:{children:ReactNode;onClick?:()=>void;secondary?:boolean;disabled?:boolean}){return <button onPointerDown={e=>e.preventDefault()} className={'button '+(secondary?'secondary':'primary')} onClick={onClick} disabled={disabled}>{children}</button>}
function Chips({options,value,onChange}:{options:string[];value:string;onChange:(s:string)=>void}){return <div className="chips">{options.map(o=><button onPointerDown={e=>e.preventDefault()} key={o} className={'chip '+(o===value?'selected':'')} aria-pressed={o===value} onClick={()=>onChange(o)}>{o}</button>)}</div>}
function ActivityIcon({kind}:{kind:Kind}){return <span className={`activity-icon activity-icon-${kind}`} aria-hidden="true"/>}
function Avatar({name,blue=false}:{name:string;blue?:boolean}){return <span className={'avatar '+(blue?'blue':'')}>{name}</span>}
function CoffeeDeck({cards,itemLabel="person",ariaLabel="Coffee chat recommendations"}:{cards:ReactNode[];itemLabel?:string;ariaLabel?:string}){
 const root=useRef<HTMLDivElement>(null),[active,setActive]=useState(0);
 useEffect(()=>{const el=root.current?.querySelector<HTMLElement>('.mobile-carousel');if(!el)return;
 let snapTimer=0;
 const centeredLeft=(slide:HTMLElement)=>slide.offsetLeft-(el.clientWidth-slide.offsetWidth)/2;
 const update=()=>{const slides=Array.from(el.querySelectorAll<HTMLElement>('.coffee-deck-slide'));let closest=0,distance=Infinity;slides.forEach((slide,i)=>{const d=Math.abs(slide.offsetLeft+slide.offsetWidth/2-(el.scrollLeft+el.clientWidth/2));if(d<distance){distance=d;closest=i}});setActive(closest);window.clearTimeout(snapTimer);snapTimer=window.setTimeout(()=>{const slide=slides[closest];if(!slide)return;const target=centeredLeft(slide);if(Math.abs(el.scrollLeft-target)>1)el.scrollTo({left:target,behavior:'smooth'})},120)};
 const resize=new ResizeObserver(()=>{el.style.setProperty('--coffee-card-width',`${Math.max(220,el.clientWidth-30)}px`);update()});resize.observe(el);el.addEventListener('scroll',update,{passive:true});return()=>{window.clearTimeout(snapTimer);resize.disconnect();el.removeEventListener('scroll',update)};
 },[]);
 function show(i:number){const el=root.current?.querySelector<HTMLElement>('.mobile-carousel');const slide=el?.querySelectorAll<HTMLElement>('.coffee-deck-slide')[i];if(el&&slide)el.scrollTo({left:slide.offsetLeft-(el.clientWidth-slide.offsetWidth)/2,behavior:'smooth'})}
 return <div className="coffee-deck" ref={root}>
 <Carousel ariaLabel={ariaLabel} className="coffee-deck-rail" contentClassName="coffee-deck-track">
 {cards.map((card,i)=><div className={'coffee-deck-slide '+(i===active?'is-current':'')} key={i} style={{zIndex:cards.length-Math.abs(i-active)}} aria-label={`${itemLabel} ${i+1} of ${cards.length}`}>{card}</div>)}
 </Carousel>
 <div className="coffee-deck-navigation"><button aria-label={`Previous ${itemLabel}`} disabled={active===0} onClick={()=>show(active-1)}><ArrowLeftIcon/></button><span aria-live="polite">{active+1} / {cards.length}</span><button aria-label={`Next ${itemLabel}`} disabled={active===cards.length-1} onClick={()=>show(active+1)}><ArrowRightIcon/></button></div>
 </div>
}
